def question(raw, offset):
    prompt, answer, *distractors = raw
    choices = [answer, *distractors]
    shift = offset % len(choices)
    choices = choices[shift:] + choices[:shift]
    item = {'prompt': prompt, 'options': choices, 'correct': (-shift) % len(choices)}
    if isinstance(prompt, tuple):
        item['prompt'], item['code'] = prompt
    return item


def build():
    assert len(MODULES) == 40 and len(FINAL) == 16
    lessons, assignments = [], []
    for index, item in enumerate(MODULES):
        number = index + 1
        section = SECTIONS[item['section']]
        assert len(item['quiz']) == 3 and len(item['assessment']) == (4 if number == len(MODULES) else 8), item['title']
        matches = list((ROOT / 'data/java-lessons').glob(f'{number:02d}-*.md'))
        assert len(matches) == 1, f'Module {number} needs exactly one lesson file'
        goals = '\n'.join('- ' + goal for goal in item['goals'])
        content = f'## Learning objectives\n{goals}\n\n' + matches[0].read_text(encoding='utf-8').strip()
        quiz = [question(raw, index + i) for i, raw in enumerate(item['quiz'])]
        lesson = {'slug': f'module-{number:02d}', 'title': item['title'], 'section': section,
                  'description': f'Section {item["section"] + 1} · {section}. ' + item['goals'][0],
                  'content': content, 'durationMinutes': item['minutes'], 'completionPercent': 90,
                  'quiz': [[q['prompt'], q['options'], q['correct']] for q in quiz]}
        lessons.append(lesson)
        lesson_id = f'{COURSE}-{lesson["slug"]}'
        if number < len(MODULES):
            assignments.append({'id': f'{COURSE}-assessment-{number:02d}', 'afterLesson': number,
                                'title': f'Module {number} Assessment: {item["title"]}',
                                'instructions': f'Eight applied questions on Module {number}, {item["title"]}. Pass to unlock Module {number + 1}.',
                                'lessonIds': [lesson_id], 'passPercent': 75, 'maxAttempts': 3, 'timeLimitSeconds': 600,
                                'questions': [question(q, index + i) for i, q in enumerate(item['assessment'])]})
        else:
            raw = item['assessment'] + FINAL
            assignments.append({'id': f'{COURSE}-final-assessment', 'afterLesson': number, 'title': 'Final Course Assessment',
                                'instructions': f'Twenty questions covering all seven sections of the course, including Module {number}, {item["title"]}. Pass to complete the course and generate your certificate.',
                                'lessonIds': [lesson_id], 'passPercent': 75, 'maxAttempts': 3, 'timeLimitSeconds': 1800,
                                'questions': [question(q, index + i) for i, q in enumerate(raw)]})
    minutes = sum(l['durationMinutes'] for l in lessons) + sum(a['timeLimitSeconds'] for a in assignments) // 60
    return {'id': COURSE, 'title': 'Java Full Stack Development', 'category': 'Technical Skills', 'difficulty': 'beginner',
            'durationMinutes': minutes, 'visibility': 'everyone', 'status': 'published', 'videoEnabled': False,
            'description': 'Follow the complete Java Full Stack roadmap in 40 modules across seven sections: programming fundamentals, databases, frontend, build tools, version control, backend and real-world projects. Each module has explanations with worked examples and a knowledge check, followed by a timed module assessment. Pass every assessment, including the final course assessment, to earn your certificate.',
            'source': {'syllabusReference': 'https://www.geeksforgeeks.org/advance-java/java-full-stack/',
                       'scope': 'Module sequence follows the reference roadmap. Explanations, examples, exercises and questions are original Shimento material.',
                       'technicalReferences': ['https://dev.java/learn/', 'https://docs.spring.io/spring-boot/reference/', 'https://react.dev/learn']},
            'contentRevision': REVISION, 'phases': SECTIONS, 'lessons': lessons, 'assignments': assignments}


def main():
    course = build()
    target = ROOT / 'data/java-full-stack-course.json'
    target.write_text(json.dumps(course, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
    print(f'Built {len(course["lessons"])} modules and {len(course["assignments"])} module assessments: {target}')


if __name__ == '__main__':
    main()
